// Bitmask DP - Recursion
// At each (mask, pos): try every unvisited city as next step
// Track (mask, pos) to define subproblem
// TIME: O(n!) without caching, SPACE: O(n) recursion depth

// Bit operations:
// mask | (1 << i)   - Set bit i (mark city i as visited)
// mask & (1 << i)   - Check if bit i is set (city i visited?)
// mask ^ (1 << i)   - Toggle bit i
// mask & ~(1 << i)  - Clear bit i
// (1 << n) - 1      - Full mask with all n bits set

// VARIATION 1: Traveling Salesman Problem (closed tour)
// dp[mask][pos] = min cost to complete tour from pos with cities in mask visited
public int tspRecursion(int[][] dist) {
    int n = dist.length;
    return solve(0, 1, n, dist);  // start at city 0, mark it visited
}

private int solve(int pos, int mask, int n, int[][] dist) {
    // All cities visited, return to start
    if (mask == (1 << n) - 1) {
        return dist[pos][0];
    }

    int result = Integer.MAX_VALUE;
    for (int next = 0; next < n; next++) {
        if ((mask & (1 << next)) == 0) {  // city not visited
            int cost = dist[pos][next] + solve(next, mask | (1 << next), n, dist);
            result = Math.min(result, cost);
        }
    }
    return result;
}

// VARIATION 2: Hamiltonian Path (no return to start)
public int hamiltonianPath(int[][] dist) {
    int n = dist.length;
    int minCost = Integer.MAX_VALUE;
    // Can start from any city
    for (int start = 0; start < n; start++) {
        minCost = Math.min(minCost, solveHamiltonian(start, 1 << start, n, dist));
    }
    return minCost;
}

private int solveHamiltonian(int pos, int mask, int n, int[][] dist) {
    if (mask == (1 << n) - 1) {
        return 0;  // No return trip needed
    }

    int result = Integer.MAX_VALUE;
    for (int next = 0; next < n; next++) {
        if ((mask & (1 << next)) == 0) {
            int cost = dist[pos][next] + solveHamiltonian(next, mask | (1 << next), n, dist);
            result = Math.min(result, cost);
        }
    }
    return result;
}

// VARIATION 3: Partition to K Equal Sum Subsets
// dp[mask] tracks if elements in mask can be partitioned so far
public boolean canPartitionKSubsets(int[] nums, int k) {
    int total = 0;
    for (int num : nums) total += num;
    if (total % k != 0) return false;
    int target = total / k;

    return solvePartition(0, 0, k, target, nums);
}

private boolean solvePartition(int mask, int currSum, int k, int target, int[] nums) {
    if (k == 0) return mask == (1 << nums.length) - 1;
    if (currSum == target) return solvePartition(mask, 0, k - 1, target, nums);

    for (int i = 0; i < nums.length; i++) {
        if ((mask & (1 << i)) == 0 && currSum + nums[i] <= target) {
            if (solvePartition(mask | (1 << i), currSum + nums[i], k, target, nums)) {
                return true;
            }
        }
    }
    return false;
}

