// Bitmask DP - Memoization
// Add cache keyed by (mask, pos) or just (mask) depending on variation
// TIME: O(2^n * n^2) for TSP, SPACE: O(2^n * n)

// VARIATION 1: TSP with 2D memo array
public int tspMemoization(int[][] dist) {
    int n = dist.length;
    int[][] memo = new int[n][1 << n];
    for (int[] row : memo) Arrays.fill(row, -1);
    return solve(0, 1, n, dist, memo);
}

private int solve(int pos, int mask, int n, int[][] dist, int[][] memo) {
    if (mask == (1 << n) - 1) {
        return dist[pos][0];
    }
    if (memo[pos][mask] != -1) return memo[pos][mask];

    int result = Integer.MAX_VALUE;
    for (int next = 0; next < n; next++) {
        if ((mask & (1 << next)) == 0) {
            int cost = dist[pos][next] + solve(next, mask | (1 << next), n, dist, memo);
            result = Math.min(result, cost);
        }
    }

    memo[pos][mask] = result;
    return result;
}

// VARIATION 2: Partition with HashMap memo (composite key)
public boolean canPartitionKSubsets(int[] nums, int k) {
    int total = 0;
    for (int num : nums) total += num;
    if (total % k != 0) return false;
    int target = total / k;

    Map<Long, Boolean> memo = new HashMap<>();
    return solvePartition(0, 0, k, target, nums, memo);
}

private boolean solvePartition(int mask, int currSum, int k, int target, 
                                int[] nums, Map<Long, Boolean> memo) {
    if (k == 0) return mask == (1 << nums.length) - 1;
    if (currSum == target) {
        return solvePartition(mask, 0, k - 1, target, nums, memo);
    }

    // Key combines mask and currSum (k is derivable from mask popcount)
    long key = ((long) mask << 20) | currSum;
    if (memo.containsKey(key)) return memo.get(key);

    for (int i = 0; i < nums.length; i++) {
        if ((mask & (1 << i)) == 0 && currSum + nums[i] <= target) {
            if (solvePartition(mask | (1 << i), currSum + nums[i], k, target, nums, memo)) {
                memo.put(key, true);
                return true;
            }
        }
    }
    memo.put(key, false);
    return false;
}

// VARIATION 3: Assignment Problem (count arrangements)
public int countArrangement(int n) {
    int[] memo = new int[1 << n];
    Arrays.fill(memo, -1);
    return solveCount(0, n, memo);
}

private int solveCount(int mask, int n, int[] memo) {
    int pos = Integer.bitCount(mask) + 1;  // 1-indexed position
    if (pos > n) return 1;
    if (memo[mask] != -1) return memo[mask];

    int count = 0;
    for (int num = 1; num <= n; num++) {
        if ((mask & (1 << (num - 1))) == 0 &&
            (num % pos == 0 || pos % num == 0)) {
            count += solveCount(mask | (1 << (num - 1)), n, memo);
        }
    }

    memo[mask] = count;
    return count;
}

