// Bitmask DP - Tabulation
// Iterate masks in increasing order (0 to 2^n - 1)
// This ensures all submasks are processed before their supersets
// TIME: O(2^n * n^2), SPACE: O(2^n * n)

// VARIATION 1: TSP
public int tspTabulation(int[][] dist) {
    int n = dist.length;
    int[][] dp = new int[1 << n][n];

    // Initialize all to infinity
    for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE);

    // Base case: start at city 0, only city 0 visited
    dp[1][0] = 0;

    // Fill table by increasing mask value
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int pos = 0; pos < n; pos++) {
            if (dp[mask][pos] == Integer.MAX_VALUE) continue;
            if ((mask & (1 << pos)) == 0) continue;  // invalid state

            // Try all unvisited cities as next destination
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0) {  // not visited
                    int newMask = mask | (1 << next);
                    dp[newMask][next] = Math.min(
                        dp[newMask][next],
                        dp[mask][pos] + dist[pos][next]
                    );
                }
            }
        }
    }

    // Find minimum cost tour (add return to start)
    int fullMask = (1 << n) - 1;
    int result = Integer.MAX_VALUE;
    for (int pos = 0; pos < n; pos++) {
        if (dp[fullMask][pos] != Integer.MAX_VALUE) {
            result = Math.min(result, dp[fullMask][pos] + dist[pos][0]);
        }
    }
    return result;
}

// VARIATION 2: Hamiltonian Path (no return)
public int hamiltonianPathTabulation(int[][] dist) {
    int n = dist.length;
    int[][] dp = new int[1 << n][n];
    for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE);

    // Can start from any city
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 0;
    }

    for (int mask = 1; mask < (1 << n); mask++) {
        for (int pos = 0; pos < n; pos++) {
            if (dp[mask][pos] == Integer.MAX_VALUE) continue;

            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0) {
                    int newMask = mask | (1 << next);
                    dp[newMask][next] = Math.min(
                        dp[newMask][next],
                        dp[mask][pos] + dist[pos][next]
                    );
                }
            }
        }
    }

    // No return trip - just find min at full mask
    int fullMask = (1 << n) - 1;
    int result = Integer.MAX_VALUE;
    for (int pos = 0; pos < n; pos++) {
        result = Math.min(result, dp[fullMask][pos]);
    }
    return result;
}

// VARIATION 3: Count Arrangements (Beautiful Arrangement)
public int countArrangementTabulation(int n) {
    int[] dp = new int[1 << n];
    dp[0] = 1;  // empty arrangement

    for (int mask = 0; mask < (1 << n); mask++) {
        int pos = Integer.bitCount(mask) + 1;  // next position to fill
        if (pos > n) continue;

        for (int num = 1; num <= n; num++) {
            int bit = 1 << (num - 1);
            if ((mask & bit) == 0 &&  // num not used
                (num % pos == 0 || pos % num == 0)) {  // divisibility
                dp[mask | bit] += dp[mask];
            }
        }
    }

    return dp[(1 << n) - 1];
}

