// Bitmask DP - Space Optimization and Advanced Techniques
// When position doesn't matter, use O(2^n) space instead of O(2^n * n)
// TIME: O(2^n * n), SPACE: O(2^n)

// VARIATION 1: Count Arrangements (no position tracking needed)
public int countArrangement(int n) {
    int[] dp = new int[1 << n];
    dp[0] = 1;

    for (int mask = 0; mask < (1 << n); mask++) {
        int pos = Integer.bitCount(mask) + 1;
        if (pos > n) continue;

        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                int num = i + 1;
                if (num % pos == 0 || pos % num == 0) {
                    dp[mask | (1 << i)] += dp[mask];
                }
            }
        }
    }

    return dp[(1 << n) - 1];
}

// SUBSET ENUMERATION: Iterate all subsets of a given mask
// Useful when combining results from all subset partitions
public List<Integer> enumerateSubsets(int mask) {
    List<Integer> subsets = new ArrayList<>();
    int subset = mask;
    while (subset > 0) {
        subsets.add(subset);
        subset = (subset - 1) & mask;  // Magic: gets next smaller subset
    }
    subsets.add(0);  // Don't forget empty subset
    return subsets;
}

// SOS DP (Sum over Subsets)
// dp[mask] = sum of arr[submask] for all submasks of mask
// TIME: O(n * 2^n) instead of O(3^n) naive
public int[] sosDP(int[] arr, int bits) {
    int size = 1 << bits;
    int[] dp = arr.clone();

    for (int i = 0; i < bits; i++) {
        for (int mask = 0; mask < size; mask++) {
            if ((mask & (1 << i)) != 0) {
                dp[mask] += dp[mask ^ (1 << i)];
            }
        }
    }
    return dp;
}

// MEET-IN-THE-MIDDLE for larger n
// Split items into two halves, process each with 2^(n/2), combine
// Example: Finding if any subset sums to target
public boolean subsetSumMeetMiddle(int[] nums, int target) {
    int n = nums.length;
    int mid = n / 2;

    // First half: all possible sums
    Set<Integer> firstHalf = new HashSet<>();
    for (int mask = 0; mask < (1 << mid); mask++) {
        int sum = 0;
        for (int i = 0; i < mid; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
            }
        }
        firstHalf.add(sum);
    }

    // Second half: check if complement exists
    int remaining = n - mid;
    for (int mask = 0; mask < (1 << remaining); mask++) {
        int sum = 0;
        for (int i = 0; i < remaining; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[mid + i];
            }
        }
        if (firstHalf.contains(target - sum)) {
            return true;
        }
    }
    return false;
}

