// TIME: O(n! * n), SPACE: O(n)

public class TSPRecursion {
    private int[][] dist;
    private int n;

    public int minCost(int[][] dist) {
        this.dist = dist;
        this.n = dist.length;
        // Start at city 0, mark it as visited (mask = 1)
        return solve(0, 1);
    }

    private int solve(int pos, int mask) {
        // Base case: all cities visited, return to start
        if (mask == (1 << n) - 1) {
            return dist[pos][0];
        }

        int result = Integer.MAX_VALUE;

        // Try each unvisited city as next destination
        for (int next = 0; next < n; next++) {
            // Check if city 'next' is not visited
            if ((mask & (1 << next)) == 0) {
                int cost = dist[pos][next] + solve(next, mask | (1 << next));
                result = Math.min(result, cost);
            }
        }

        return result;
    }
}

