// Traveling Salesman Problem - Memoization
// TIME: O(2^n * n^2), SPACE: O(2^n * n)

import java.util.Arrays;

public class TSPMemoization {
    private int[][] dist;
    private int[][] memo;
    private int n;

    public int minCost(int[][] dist) {
        this.dist = dist;
        this.n = dist.length;
        this.memo = new int[n][1 << n];

        // Initialize memo with -1 (uncomputed)
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }

        return solve(0, 1);
    }

    private int solve(int pos, int mask) {
        // Base case: all cities visited
        if (mask == (1 << n) - 1) {
            return dist[pos][0];
        }

        // Check memo
        if (memo[pos][mask] != -1) {
            return memo[pos][mask];
        }

        int result = Integer.MAX_VALUE;

        for (int next = 0; next < n; next++) {
            if ((mask & (1 << next)) == 0) {
                int cost = dist[pos][next] + solve(next, mask | (1 << next));
                result = Math.min(result, cost);
            }
        }

        memo[pos][mask] = result;
        return result;
    }
}

