// Traveling Salesman Problem - Tabulation
// TIME: O(2^n * n^2), SPACE: O(2^n * n)

import java.util.Arrays;

public class TSPTabulation {
    public int minCost(int[][] dist) {
        int n = dist.length;
        int[][] dp = new int[1 << n][n];

        // Initialize all states to infinity
        for (int[] row : dp) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        // Base case: start at city 0, only city 0 visited, cost 0
        dp[1][0] = 0;

        // Process masks in increasing order
        for (int mask = 1; mask < (1 << n); mask++) {
            for (int pos = 0; pos < n; pos++) {
                // Skip unreachable states
                if (dp[mask][pos] == Integer.MAX_VALUE) continue;
                // Skip invalid states (pos not in mask)
                if ((mask & (1 << pos)) == 0) continue;

                // Try all unvisited cities
                for (int next = 0; next < n; next++) {
                    if ((mask & (1 << next)) == 0) {
                        int newMask = mask | (1 << next);
                        int newCost = dp[mask][pos] + dist[pos][next];
                        dp[newMask][next] = Math.min(dp[newMask][next], newCost);
                    }
                }
            }
        }

        // Find minimum cost tour (complete mask + return to start)
        int fullMask = (1 << n) - 1;
        int result = Integer.MAX_VALUE;
        for (int pos = 0; pos < n; pos++) {
            if (dp[fullMask][pos] != Integer.MAX_VALUE) {
                result = Math.min(result, dp[fullMask][pos] + dist[pos][0]);
            }
        }

        return result;
    }
}

