// Count Beautiful Arrangements - Space Optimized
// When position is implicit (derived from popcount), use O(2^n) space
// TIME: O(2^n * n), SPACE: O(2^n)

public class BeautifulArrangement {
    public int countArrangement(int n) {
        int[] dp = new int[1 << n];
        dp[0] = 1;  // Empty arrangement is valid

        for (int mask = 0; mask < (1 << n); mask++) {
            // Position is determined by how many numbers we've placed
            int pos = Integer.bitCount(mask) + 1;
            if (pos > n) continue;

            for (int i = 0; i < n; i++) {
                // If number (i+1) not yet used
                if ((mask & (1 << i)) == 0) {
                    int num = i + 1;
                    // Check divisibility condition
                    if (num % pos == 0 || pos % num == 0) {
                        dp[mask | (1 << i)] += dp[mask];
                    }
                }
            }
        }

        return dp[(1 << n) - 1];
    }
}

// Meet-in-the-Middle for larger n (subset sum variant)
// Splits problem into two halves, each with 2^(n/2) states
import java.util.*;

public class MeetInMiddle {
    public boolean canPartition(int[] nums, int target) {
        int n = nums.length;
        int mid = n / 2;

        // Generate all subset sums for first half
        Set<Integer> firstHalf = new HashSet<>();
        for (int mask = 0; mask < (1 << mid); mask++) {
            int sum = 0;
            for (int i = 0; i < mid; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += nums[i];
                }
            }
            firstHalf.add(sum);
        }

        // Check second half against complements in first half
        int remaining = n - mid;
        for (int mask = 0; mask < (1 << remaining); mask++) {
            int sum = 0;
            for (int i = 0; i < remaining; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += nums[mid + i];
                }
            }
            if (firstHalf.contains(target - sum)) {
                return true;
            }
        }
        return false;
    }
}

